package reconstruct

import (
	"context"
	"log/slog"

	"github.com/bnb-chain/tss-lib/v2/crypto/vss"
	"github.com/bnb-chain/tss-lib/v2/ecdsa/keygen"
	"github.com/bnb-chain/tss-lib/v2/tss"
	"github.com/decred/dcrd/dcrec/secp256k1/v4"

	"github.com/nsuiteio/nst-mpc-key-export/utility/errutil"
	"github.com/nsuiteio/nst-mpc-key-export/utility/keyutil"
	"github.com/nsuiteio/nst-mpc-key-export/utility/logutil"
	"github.com/nsuiteio/nst-mpc-key-export/utility/strutil"
)

func ReconstructECDSA(
	ctx context.Context,
	threshold int,
	shares []*keygen.LocalPartySaveData,
) (*secp256k1.PrivateKey, error) {
	logger := logutil.Get(ctx).With(
		slog.String("function", "ReconstructECDSA"),
		slog.Int("threshold", threshold),
		slog.Int("num_parties", len(shares)),
	)
	logger.Info("started")

	var vssShares = make(vss.Shares, len(shares))
	for i, share := range shares {
		vssShare := &vss.Share{
			Threshold: threshold,
			ID:        share.ShareID,
			Share:     share.Xi,
		}
		vssShares[i] = vssShare
	}

	ec := tss.S256()

	d, err := vssShares.ReConstruct(ec)
	if err != nil {
		return nil, errutil.Wrap(err)
	}

	prvKey := secp256k1.PrivKeyFromBytes(d.Bytes())
	logger.Info("finished")
	return prvKey, nil
}

func SampleECDSA(ctx context.Context) ([]byte, error) {
	threshold := 2
	keyShares := []string{
		"",
		"",
		"",
	}

	shares := make([]*keygen.LocalPartySaveData, len(keyShares))
	for i, keyShare := range keyShares {
		bs, err := strutil.FromHex(keyShare)
		if err != nil {
			return nil, errutil.Wrap(err)
		}
		share, err := keyutil.LocalDataFromBytesECDSA(ctx, bs)
		if err != nil {
			return nil, errutil.Wrap(err)
		}
		shares[i] = share
	}

	prvKey, err := ReconstructECDSA(ctx, threshold, shares)
	if err != nil {
		return nil, errutil.Wrap(err)
	}
	keyBs := prvKey.Serialize()
	return keyBs, nil
}
